import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';

// Images are generated by the built-in tool. This helper saves the returned
// sources and normalizes them serially, so there is only one manifest writer.
const input = JSON.parse(process.argv[2]);
const failed = [...(input.failed ?? [])];
const saved = [];
await mkdir('output/item-catalog/generated-jobs', { recursive: true });
for (const job of input.jobs ?? []) {
  try {
    await writeFile(`output/item-catalog/generated-jobs/${job.id}.json`, JSON.stringify(job, null, 2) + '\n');
    const output = execFileSync(process.execPath, [
      'scripts/content/normalize-shared-item-icon.mjs',
      '--id', job.id, '--source', job.source, '--destination', job.path,
    ], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    saved.push(JSON.parse(output.trim()));
  } catch (error) {
    failed.push({ id: job.id, error: String(error.stderr || error.message || error) });
  }
}
const manifest = JSON.parse(await readFile('assets/item-catalog/generation-manifest.json', 'utf8'));
const requests = JSON.parse(await readFile('assets/item-catalog/art-requests.json', 'utf8'));
const completed = Object.keys(manifest.entries).length;
const state = {
  running: input.running !== false,
  completed,
  pending: requests.length - completed,
  batchGenerated: completed - input.baseCompleted,
  batchTotal: input.batchTotal,
  lastId: saved.at(-1)?.id ?? null,
  failed,
};
await writeFile('output/item-catalog/worker-status.json', JSON.stringify(state, null, 2) + '\n');
console.log(JSON.stringify({ saved, state }));
